('vml-036','visual-math','What comes next?','["30","32","35","36"]','35','The pattern increases by 5: 15, 20, 25, 30, 35.',136,'medium','Patterns','visual_question','{"visual":{"kind":"pattern","values":[15,20,25,30]}}','Count forward by 5.','question-enter',null),
('vml-037','visual-math','How many counters are in all four groups?','["18","19","20","21"]','20','There are 5 + 4 + 6 + 5 counters. That equals 20.',137,'hard','Addition','visual_question','{"visual":{"kind":"counters_addition","groups":[5,4,6,5]}}','Add each group carefully.','question-enter',null),
('vml-038','visual-math','How many more counters are in the larger group?','["6","7","8","9"]','8','The groups have 7 and 15 counters. 15 - 7 = 8.',138,'hard','Subtraction','visual_question','{"visual":{"kind":"counters_addition","groups":[7,15]}}','Find the difference.','question-enter',null),
('vml-039','visual-math','Which number is greatest?','["68","86","78","88"]','88','88 is the greatest number shown.',139,'hard','Comparison','visual_question','{"visual":{"kind":"number_cards","numbers":[68,86,78,88]}}','Compare the tens and then the ones.','question-enter',null),
